const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mountIsa = ee.Geometry.Point([139.492, -20.725]).buffer(50000); // 50km buffer
  const townsville = ee.Geometry.Point([146.817, -19.259]).buffer(50000); // 50km buffer
  const startDate = '2019-01-27';
  const endDate = '2019-02-10';

  // 2. Data Acquisition - CHIRPS for rainfall
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate);

  const chirpsSize = chirps.size().getInfo();
  console.log(`CHIRPS Images: ${chirpsSize}`);

  if (chirpsSize === 0) {
    console.log("No rainfall data found for the period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate total rainfall
  const totalRainfall = chirps.select('precipitation').sum();

  // 4. Calculate rainfall for each region and check pixel counts
  const mountIsaRainfall = totalRainfall.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: mountIsa,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  const townsvilleRainfall = totalRainfall.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: townsville,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  // Check pixel counts to ensure valid data
  const mountIsaCount = totalRainfall.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: mountIsa,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  const townsvilleCount = totalRainfall.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: townsville,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  const [mountIsaRain, townsvilleRain, mountIsaPixels, townsvillePixels] = await Promise.all([
    mountIsaRainfall.getInfo(),
    townsvilleRainfall.getInfo(),
    mountIsaCount.getInfo(),
    townsvilleCount.getInfo()
  ]);

  console.log(`Mount Isa: ${mountIsaRain?.toFixed(1)}mm, Pixels: ${mountIsaPixels}`);
  console.log(`Townsville: ${townsvilleRain?.toFixed(1)}mm, Pixels: ${townsvillePixels}`);

  // 5. Validation & Final Answer
  if (mountIsaRain === null || townsvilleRain === null || 
      mountIsaPixels === 0 || townsvillePixels === 0) {
    console.log("No valid pixels in one or both regions.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (isNaN(mountIsaRain) || isNaN(townsvilleRain) || 
      mountIsaRain < 0 || townsvilleRain < 0) {
    console.log("Invalid rainfall values calculated.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if both regions had at least 450mm (45cm) of rainfall
  const mountIsaMetTarget = mountIsaRain >= 450;
  const townsvilleMetTarget = townsvilleRain >= 450;

  console.log(`Mount Isa >=450mm: ${mountIsaMetTarget}`);
  console.log(`Townsville >=450mm: ${townsvilleMetTarget}`);

  if (mountIsaMetTarget && townsvilleMetTarget) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
